import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;
import java.lang.invoke.MethodHandle;
import java.lang.invoke.MethodHandles;
import java.lang.invoke.MethodType;
import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.Method;

public class Main {
    @Retention(RetentionPolicy.RUNTIME)
    @Target({ElementType.FIELD, ElementType.METHOD})
    @interface Label {
        String value();
    }

    static class User {
        @Label("display-name")
        private String name;

        private User(String name) {
            this.name = name;
        }

        @Label("greeting")
        private String greet(String prefix) {
            return prefix + ", " + name;
        }
    }

    public static void main(String[] args) throws Throwable {
        Class<User> literal = User.class;
        Class<?> forName = Class.forName("Main$User");
        assert literal == forName;

        Constructor<User> constructor = literal.getDeclaredConstructor(String.class);
        constructor.setAccessible(true);
        User user = constructor.newInstance("Ada");

        Field nameField = literal.getDeclaredField("name");
        nameField.setAccessible(true);
        assert nameField.get(user).equals("Ada");
        nameField.set(user, "Grace");

        Method greet = literal.getDeclaredMethod("greet", String.class);
        greet.setAccessible(true);
        String reflectValue = (String) greet.invoke(user, "Hi");
        System.out.println("reflect invoke: " + reflectValue);

        Label fieldLabel = nameField.getAnnotation(Label.class);
        Label methodLabel = greet.getAnnotation(Label.class);
        System.out.println("labels: " + fieldLabel.value() + ", " + methodLabel.value());

        MethodHandle privateGreet = MethodHandles.privateLookupIn(User.class, MethodHandles.lookup())
                .findVirtual(User.class, "greet", MethodType.methodType(String.class, String.class));
        System.out.println("method handle private: " + (String) privateGreet.invoke(user, "Hello"));

        Field stringValue = String.class.getDeclaredField("value");
        System.out.println("String.value trySetAccessible: " + stringValue.trySetAccessible());

        assert "Hi, Grace".equals(reflectValue);
    }
}
